export function OrgChart({
  rootName = "{{rootName}}",
  rootTitle = "{{rootTitle}}",
  layout = "{{layout}}",
  color = "{{color}}",
  showTitles = {{showTitles}},
}) {
  const nodeStyle = { border: `1.5px solid ${color}`, borderRadius: 10, padding: "8px 14px", textAlign: "center", minWidth: 120, background: "#FAF7F2" };
  return (
    <div style={{ display: "flex", flexDirection: layout === "horizontal" ? "row" : "column", alignItems: layout === "horizontal" ? "flex-start" : "center", gap: 18, font: "14px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <div style={{ ...nodeStyle, background: color }}>
        <strong>{rootName}</strong>
        {showTitles && <span style={{ display: "block", fontSize: 12, opacity: 0.75 }}>{rootTitle}</span>}
      </div>
      <div style={{ display: "flex", flexDirection: layout === "horizontal" ? "column" : "row", gap: layout === "horizontal" ? 12 : 24 }}>
        <div style={nodeStyle}><strong>Alex Chen</strong>{showTitles && <span style={{ display: "block", fontSize: 12, opacity: 0.75 }}>VP Engineering</span>}</div>
        <div style={nodeStyle}><strong>Jordan Lee</strong>{showTitles && <span style={{ display: "block", fontSize: 12, opacity: 0.75 }}>VP Design</span>}</div>
      </div>
    </div>
  );
}
